import { db } from './firebase.js';
import { doc, getDoc, setDoc, onSnapshot } from "https://www.gstatic.com/firebasejs/12.15.0/firebase-firestore.js";

const getState = () => {
  if (typeof window !== 'undefined') {
    if (!window.__DSG_STATE__) {
      window.__DSG_STATE__ = {
        memoryData: null,
        memoryNews: null,
        memoryGallery: null,
        initialized: false
      };
    }
    return window.__DSG_STATE__;
  }
  return { memoryData: null, memoryNews: null, memoryGallery: null, initialized: false };
};

// Lightweight IndexedDB helper for resilient offline storage beyond 5MB
const openDB = () => {
  return new Promise((resolve) => {
    try {
      const req = indexedDB.open('dsg_database_v2', 1);
      req.onupgradeneeded = (e) => {
        const d = e.target.result;
        if (!d.objectStoreNames.contains('keyval')) {
          d.createObjectStore('keyval');
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
    } catch(e) {
      resolve(null);
    }
  });
};

const idbGet = async (key) => {
  try {
    const database = await openDB();
    if (!database) return null;
    return new Promise((resolve) => {
      const tx = database.transaction('keyval', 'readonly');
      const store = tx.objectStore('keyval');
      const req = store.get(key);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  } catch (e) {
    return null;
  }
};

const idbSet = async (key, val) => {
  try {
    const database = await openDB();
    if (!database) return false;
    return new Promise((resolve) => {
      const tx = database.transaction('keyval', 'readwrite');
      const store = tx.objectStore('keyval');
      store.put(val, key);
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => resolve(false);
    });
  } catch (e) {
    return false;
  }
};

const parseArticleDate = (a) => {
  if (!a) return 0;
  if (a.createdAt && typeof a.createdAt === 'number') return a.createdAt;
  const d = a.date || '';
  if (d.includes('-')) {
    const p = d.split('-');
    if (p.length === 3) {
      const dt = new Date(parseInt(p[0]), parseInt(p[1]) - 1, parseInt(p[2])).getTime();
      if (!isNaN(dt) && dt > 0) return dt;
    }
  }
  if (d.includes('.')) {
    const p = d.split('.');
    if (p.length === 3) {
      let yr = parseInt(p[2]);
      if (yr < 100) yr += 2000;
      const dt = new Date(yr, parseInt(p[1]) - 1, parseInt(p[0])).getTime();
      if (!isNaN(dt) && dt > 0) return dt;
    }
  }
  if (a.lastUpdated && typeof a.lastUpdated === 'number') return a.lastUpdated;
  return 0;
};

const sortArticles = (articles) => {
  if (!Array.isArray(articles)) return [];
  return [...articles].sort((a, b) => {
    const timeA = parseArticleDate(a);
    const timeB = parseArticleDate(b);
    if (timeB !== timeA) return timeB - timeA;
    return (parseInt(b.id) || 0) - (parseInt(a.id) || 0);
  });
};

function trySetLocal(key, dataStr) {
  try {
    localStorage.setItem(key, dataStr);
  } catch (e) {
    console.warn("localStorage quota exceeded for key:", key);
  }
}

